    for &b in line {
        crate::ffi::put_byte(b);
    }
    crate::ffi::put_byte(b'\n');
}

pub fn print_hex_char_line(char_hex: i8) {
    let hex_str = format!("{:02x}\n", char_hex as u8);
    for &b in hex_str.as_bytes() {
        crate::ffi::put_byte(b);
    }
}

